// Riemann--Roch extraction from a target KM space. No scalar-recovery oracle.
#include "complete_km_arithmetic.hpp"
#include "moving_transpose_arithmetic.hpp"
EBPoly kd_section(const Vector& c,const std::vector<Monomial>& mons){require(c.size()==mons.size(),"decoder section width");EBPoly p;for(size_t i=0;i<c.size();++i)p.add(mons[i],c[i]);return p;}
std::pair<CFPoly,CFPoly> kd_local(const EBPoly& f,const BasePoint& p,int n){std::vector<Z> c(size_t(n+1),Z(0));c[size_t(n)]=Z(1);CFPoly mod(c),t{Z(0),Z(1)},x{Z(p.x)},y{p.y};bool xlocal=f.partial(1).eval(Z(p.x),p.y)!=Z(0);if(xlocal)x=x+t;else{require(f.partial(0).eval(Z(p.x),p.y)!=Z(0),"decoder smooth local chart");y=y+t;}auto df=f.partial(xlocal?1:0);for(int k=1;k<n;k*=2){auto error=cm_curve(f,mod,x,y),derivative=cm_curve(df,mod,x,y);if(xlocal)y=(y-error*cm_inverse(derivative,mod))%mod;else x=(x-error*cm_inverse(derivative,mod))%mod;}require(cm_curve(f,mod,x,y).degree()<0,"decoder exact local curve");return {x,y};}
Space kd_jets(const EBPoly& f,const BasePoint& p,const std::vector<Monomial>& mons,int n){auto[x,y]=kd_local(f,p,n);std::vector<Z> c(size_t(n+1),Z(0));c[size_t(n)]=Z(1);CFPoly mod(c);Space rows(size_t(n),Vector(mons.size(),Z(0)));for(size_t j=0;j<mons.size();++j){auto e=mons[j];auto value=(pc_power_mod(x,e[0],mod)*pc_power_mod(y,e[1],mod))%mod;for(int k=0;k<n;++k)rows[size_t(k)][j]=value.at(k);}return rows;}
Vector kd_coefficients(const Space& basis,const Vector& value){int n=int(basis.size());auto canonical=row_basis(basis,evaluation_count);require(int(canonical.size())==n,"decoder independent evaluation basis");std::vector<int> pivots;for(auto& row:canonical){int p=0;while(p<evaluation_count&&row[size_t(p)]==Z(0))++p;require(p<evaluation_count,"decoder evaluation pivot");pivots.push_back(p);}std::vector<Vector> columns;for(auto& row:basis){Vector c;for(int j:pivots)c.push_back(row[size_t(j)]);columns.push_back(c);}Vector target;for(int j:pivots)target.push_back(value[size_t(j)]);auto coeff=gb_solve(columns,target);require(linear_combination(coeff,basis)==value,"decoder full evaluation interpolation");return coeff;}
EBPoly kd_power(EBPoly p,int n){EBPoly r(Z(1));while(n){if(n&1)r=r*p;n>>=1;if(n)p=p*p;}return r;}
EBPoly kd_transform(const EBPoly& p,int degree,const Z& a,const Z& l){EBPoly x,y;x.add({1,0},Z(1));x.add({0,1},-l);y.add({0,1},Z(1));EBPoly z=EBPoly(Z(1))-x.scale(a),out;for(auto& [e,c]:p.terms){require(e[0]+e[1]<=degree,"decoder homogeneous degree");out=out+(kd_power(x,e[0])*kd_power(y,e[1])*kd_power(z,degree-e[0]-e[1])).scale(c);}return out;}
CFPoly kd_recover_y(const CFPoly& u,const EBPoly& f,const EBPoly& n,int depth=0){require(depth<=24,"decoder residue splitting depth");CFResidue::support=u;try{auto g=std::get<0>(xgcd(cf_residue_y(f),cf_residue_y(n)));require(g.degree()==1,"decoder separated intersection y");return (-g.at(0)/g.at(1)).a;}catch(const CFSplit& split){auto p=split.factor.monic(),q=u.exact(p).monic();require(p.degree()>0&&q.degree()>0&&cf_gcd(p,q).degree()==0,"decoder squarefree residue split");auto a=kd_recover_y(p,f,n,depth+1),b=kd_recover_y(q,f,n,depth+1);return cf_crt(p,a,q,b);}}
CFPoly kd_characteristic(const CFPoly& u,const CFPoly& z){int n=u.degree();std::vector<std::vector<CFPoly>> matrix(size_t(n),std::vector<CFPoly>(size_t(n)));CFPoly x{Z(0),Z(1)},power{Z(1)};for(int j=0;j<n;++j){auto v=(z*power)%u;for(int i=0;i<n;++i){matrix[size_t(i)][size_t(j)]=CFPoly{-v.at(i)};if(i==j)matrix[size_t(i)][size_t(j)]=matrix[size_t(i)][size_t(j)]+x;}power=(power*x)%u;}auto out=cf_determinant(matrix).monic();require(out.degree()==n,"decoder closed projection characteristic");return out;}
struct KDResult {MCycle cycle;EBPoly numerator;CFPoly total,negative_support,base_support,cubic;Z chart,shear;int rr_dimension=0;std::vector<std::string> chart_rejections,shear_rejections;Class encoded;};
struct KMDecoder {
    QuarticKM& km;CMAdapter& adapter;EBPoly f,g0,denominator;CFPoly ru,rv;std::vector<Monomial> mons6;std::vector<EBPoly> numerator_basis;Space candidates,multiplier;int product_rank=0;
    KMDecoder(QuarticKM& k,CMAdapter& aa,EBPoly ff,const Json& actual):km(k),adapter(aa),f(std::move(ff)),g0(br_read_poly(actual.at("reference_cubic"))),ru(pc_read_poly(actual.at("residual_U"))),rv(pc_read_poly(actual.at("residual_V"))),mons6(monomial_basis(6)){
        require(ru.degree()==3&&cf_gcd(ru,cf_derivative(ru)).degree()==0,"decoder residual3 squarefree");require(cf_evaluate(f,ru,rv).degree()<0&&cf_evaluate(g0,ru,rv).degree()<0,"decoder residual incidence");CFPoly ref{Z(1)};for(int i:adapter.reference){auto& p=km.points[size_t(i)];for(int j=0;j<3;++j)ref=ref*CFPoly{-Z(p.x),Z(1)};auto jets=kd_jets(f,p,monomial_basis(3),3);Vector coeff;for(auto m:monomial_basis(3)){auto hit=g0.terms.find(m);coeff.push_back(hit==g0.terms.end()?Z(0):hit->second);}for(auto& row:jets){Z sum;for(size_t j=0;j<row.size();++j)sum=sum+row[j]*coeff[j];require(sum==Z(0),"decoder reference cubic multiplicity3");}}
        require(cf_resultant(f,g0).monic()==ref*ru,"decoder complete reference cubic intersection");require(cf_gcd(ref,ru).degree()==0,"decoder disjoint fixed residual");std::vector<Z> inf(5,Z(0));for(auto& [e,c]:f.terms)if(e[0]+e[1]==4)inf[size_t(e[1])]=inf[size_t(e[1])]+c;require(CFPoly(inf).degree()==4,"decoder infinity chart");ct_irreducible(CFPoly(inf));
        Space constraints;for(int i:adapter.reference){auto rows=kd_jets(f,km.points[size_t(i)],mons6,2);constraints.insert(constraints.end(),rows.begin(),rows.end());}Space closed(3,Vector(mons6.size(),Z(0)));CFPoly x{Z(0),Z(1)};for(size_t j=0;j<mons6.size();++j){auto e=mons6[j];auto value=(pc_power_mod(x,e[0],ru)*pc_power_mod(rv,e[1],ru))%ru;for(int i=0;i<3;++i)closed[size_t(i)][j]=value.at(i);}constraints.insert(constraints.end(),closed.begin(),closed.end());auto basis=nullspace(constraints,int(mons6.size()));require(basis.size()==13,"decoder L(B) dimension13");EBPoly line;line.add({1,0},Z(1));line.add({0,0},Z(-km.fibers[0].x));denominator=kd_power(line,3)*g0;
        for(auto& coeff:basis){auto numerator=kd_section(coeff,mons6);numerator_basis.push_back(numerator);Vector values;for(int i:km.pool){auto& p=km.points[size_t(i)];Z d=denominator.eval(Z(p.x),p.y),n=numerator.eval(Z(p.x),p.y);if(d!=Z(0))values.push_back(n/d);else{auto[lx,ly]=kd_local(f,p,2);CFPoly mod{Z(0),Z(0),Z(1)},ds=cm_curve(denominator,mod,lx,ly),ns=cm_curve(numerator,mod,lx,ly);require(ds.at(0)==Z(0)&&ns.at(0)==Z(0)&&ds.at(1)!=Z(0),"decoder removable residual evaluation");values.push_back(ns.at(1)/ds.at(1));}}candidates.push_back(values);}require(row_basis(candidates,evaluation_count).size()==13,"decoder candidate evaluation rank13");
        Space mconstraints;for(int i:adapter.reference){Vector row;auto& p=km.points[size_t(i)];for(auto e:mons6)row.push_back(zpow(Z(p.x),e[0])*zpow(p.y,e[1]));mconstraints.push_back(row);}auto mbasis=nullspace(mconstraints,int(mons6.size()));require(mbasis.size()==19,"decoder multiplier dimension19");auto raw=km.evaluate_basis(2);for(auto& c:mbasis)multiplier.push_back(linear_combination(c,raw));auto ambient=row_basis(km.v3,evaluation_count);Space products;for(auto& c:candidates)for(auto& m:multiplier){auto p=hadamard(c,m);require(all_zero(residual(p,ambient)),"decoder product in actual ambient");products.push_back(p);}product_rank=int(row_basis(products,evaluation_count).size());require(product_rank==34,"decoder multiplication ambient rank34");
    }
    void validate(const Class& c)const{require(c.w.size()==22&&row_basis(c.w,evaluation_count).size()==22,"opaque KM class dimension22");auto ambient=row_basis(km.v3,evaluation_count);for(auto& row:c.w)require(all_zero(residual(row,ambient)),"opaque KM ambient membership");}
    KDResult decode(const Class& c,bool force_bad){
        validate(c);KDResult out;auto negative=km.negate(c);auto sections=preimage(candidates,multiplier,negative.w);require(!sections.empty(),"decoder nonzero degree3 RR space");out.rr_dimension=int(sections.size());auto coeff=kd_coefficients(candidates,sections[0]);for(size_t i=0;i<coeff.size();++i)out.numerator=out.numerator+numerator_basis[i].scale(coeff[i]);std::vector<EBPoly> wsections;for(auto& row:negative.w)wsections.push_back(kd_section(kd_coefficients(km.v3,row),km.mons));std::vector<Z> charts;if(force_bad){Z qx(km.points[size_t(adapter.reference[0])].x);require(qx!=Z(0),"forced decoder chart reference x");charts.push_back(-Z(1)/qx);}for(int a=0;a<=24;++a)charts.push_back(Z(a));bool chart_found=false;
        for(auto a:charts){auto cf=kd_transform(f,4,a,Z(0)),cn=kd_transform(out.numerator,6,a,Z(0));auto support=cf_resultant(cf,cn);if(support.degree()!=24){out.chart_rejections.push_back(a.x.get_str()+":degree"+std::to_string(support.degree()));continue;}out.chart=a;chart_found=true;break;}require(chart_found,"decoder projective chart bound");if(force_bad)require(!out.chart_rejections.empty(),"forced bad projective chart rejected");std::vector<Z> shears;
        if(force_bad){auto& p=km.points[size_t(adapter.reference[0])];auto& q=km.points[size_t(adapter.reference[1])];Z pd=Z(1)+out.chart*Z(p.x),qd=Z(1)+out.chart*Z(q.x),px=Z(p.x)/pd,py=p.y/pd,qx=Z(q.x)/qd,qy=q.y/qd;require(py!=qy,"forced decoder distinct reference y");shears.push_back((qx-px)/(py-qy));}for(int l=0;l<=308;++l)shears.push_back(Z(l));CFPoly total_y;bool separated=false;
        for(auto l:shears){try{auto cf=kd_transform(f,4,out.chart,l),cn=kd_transform(out.numerator,6,out.chart,l);auto leading=cf.terms.find({0,4});require(leading!=cf.terms.end()&&leading->second!=Z(0),"decoder projection center outside curve");auto support=cf_resultant(cf,cn).monic();require(support.degree()==24,"decoder full affine intersection24");auto rad=support.exact(cf_gcd(support,cf_derivative(support))).monic();auto y=kd_recover_y(rad,cf,cn);require(cf_evaluate(cf,rad,y).degree()<0&&cf_evaluate(cn,rad,y).degree()<0,"decoder radical incidence");auto dy=cf.partial(1);require(cf_gcd(cf_evaluate(dy,rad,y),rad).degree()==0,"decoder unramified projection");for(int precision=1;precision<24;precision*=2)y=(y-cf_evaluate(cf,support,y)*cm_inverse(cf_evaluate(dy,support,y),support))%support;require(cf_evaluate(cf,support,y).degree()<0&&cf_evaluate(cn,support,y).degree()<0,"decoder full multiplicity incidence");out.total=support;out.shear=l;total_y=y;separated=true;break;}catch(const std::exception& e){out.shear_rejections.push_back(l.x.get_str()+":"+e.what());}}
        require(separated,"decoder separating projection bound");if(force_bad)require(!out.shear_rejections.empty(),"forced bad shear rejected");out.negative_support=out.total;for(auto& w:wsections){auto transformed=kd_transform(w,9,out.chart,out.shear);out.negative_support=cf_gcd(out.negative_support,cf_evaluate(transformed,out.total,total_y));}require(out.negative_support.degree()==12,"decoder recovered negative divisor degree12");out.base_support=CFPoly{Z(1)};for(int i:adapter.reference){auto& p=km.points[size_t(i)];Z z=(Z(p.x)+out.shear*p.y)/(Z(1)+out.chart*Z(p.x));for(int j=0;j<2;++j)out.base_support=out.base_support*CFPoly{-z,Z(1)};}CFPoly r{Z(0),Z(1)},den=CFPoly{Z(1)}+r.scale(out.chart);auto projected=((r+rv.scale(out.shear))*cm_inverse(den,ru))%ru;out.base_support=out.base_support*kd_characteristic(ru,projected);require(out.base_support.degree()==9,"decoder fixed base degree9");out.cubic=out.total.exact(out.negative_support*out.base_support).monic();require(out.cubic.degree()==3,"decoder effective degree3 residual");auto yy=total_y%out.cubic,xx=(r-yy.scale(out.shear))%out.cubic,denom=CFPoly{Z(1)}-xx.scale(out.chart),inverse=cm_inverse(denom,out.cubic);auto original_x=(xx*inverse)%out.cubic,original_y=(yy*inverse)%out.cubic;require(cm_curve(f,out.cubic,original_x,original_y).degree()<0,"decoder original quartic incidence");
        GBSource::modulus=CFPoly{Z(0),Z(1)};std::vector<GBSource> uc,xc,yc;for(auto a:out.cubic.c)uc.emplace_back(CFPoly{a});for(auto a:original_x.c)xc.emplace_back(CFPoly{a});for(auto a:original_y.c)yc.emplace_back(CFPoly{a});MAlgebra algebra(1,GBP(uc),GBP(xc),GBP(yc));out.cycle=algebra.cycle(f);out.encoded=adapter.encode(out.cycle,1).value;require(km.equal(out.encoded,c),"opaque decoded divisor reencodes original class");return out;
    }
};
void kd_emit(const KDResult& r){std::cout<<"{\"rr_dimension\":"<<r.rr_dimension<<",\"chart_a\":\""<<r.chart.x<<"\",\"shear_lambda\":\""<<r.shear.x<<"\",\"chart_rejections\":[";for(size_t i=0;i<r.chart_rejections.size();++i)std::cout<<(i?",":"")<<std::quoted(r.chart_rejections[i]);std::cout<<"],\"shear_rejections\":[";for(size_t i=0;i<r.shear_rejections.size();++i)std::cout<<(i?",":"")<<std::quoted(r.shear_rejections[i]);std::cout<<"],\"numerator\":";eb_emit_poly(std::cout,r.numerator);std::cout<<",\"total_support\":";cf_emit_poly(r.total);std::cout<<",\"negative_support\":";cf_emit_poly(r.negative_support);std::cout<<",\"base_support\":";cf_emit_poly(r.base_support);std::cout<<",\"cubic\":";cf_emit_poly(r.cubic);std::cout<<",\"cycle\":";cm_emit_cycle(r.cycle);std::cout<<",\"reencoded_class\":";pc_emit_class(r.encoded);std::cout<<'}';}
int main(int argc,char** argv){try{
    require(argc==7,"usage: opaque_km study global bridge formal actual-kernel primary|panel");std::string root=argv[1],mode=argv[6];require(mode=="primary"||mode=="panel","frozen opaque decoder mode");initialize_cover(read_json(root+"/inputs/p192-d7-prym.json"));Level2Input input;auto global=read_json(argv[2]),bridge=read_json(argv[3]),formal=read_json(argv[4]),actual=read_json(argv[5]),model=read_json(root+"/evidence/p192-d7-kernel3-plane-quartic.json"),points=read_json(root+"/evidence/destination-relations-v2/result.json");EBPoly f;for(auto& row:model.at("terms").arr){auto e=row.at("exponents");f.add({e.arr[0].integer(),e.arr[1].integer()},Z(mpz_class(row.at("coefficient").scalar)));}MMap map(global,f);QuarticKM km(model,points);CMAdapter adapter(km,f,formal);KMDecoder decoder(km,adapter,f,actual);auto& rows=bridge.at("images").arr;G pg=cm_source(rows[0]),p=cm_source(rows[2]);Class cg=gb_class(rows[0].at("class_space"),km);std::vector<Class> classes;std::vector<G> expected;std::vector<std::string> labels;if(mode=="primary"){classes.push_back(cg);expected.push_back(pg.times(3));labels.push_back("pullG");}else{classes={km.identity,cg,km.add(cg,cg),gb_class(rows[2].at("class_space"),km),cm_rational_point_class(km,f,1)};expected={G{},pg.times(3),pg.times(6),p.times(3)};labels={"zero","pullG","KM-double-pullG","generic-source-point","target-point1"};auto& q=points.at("points").arr[1];int anchor=km.fibers[0].support[0];auto& q0=points.at("points").arr[size_t(anchor)];expected.push_back(tr_fiber(map,Z(mpz_class(q.at("x").scalar)),Z(mpz_class(q.at("y").scalar))).reduced.add(tr_fiber(map,Z(mpz_class(q0.at("x").scalar)),Z(mpz_class(q0.at("y").scalar))).reduced.neg()));}
    auto qref=points.at("points").arr[0];CFPoly linear{Z(0),Z(1)};MTWitness rw;auto aref=mt_point(map,linear,CFPoly{Z(mpz_class(qref.at("x").scalar))},CFPoly{Z(mpz_class(qref.at("y").scalar))},false,rw);G reference;for(int i:adapter.reference){auto& q=km.points[size_t(i)];std::vector<MTWitness> ws;reference=reference.add(mt_normalized(map,linear,CFPoly{Z(q.x)},CFPoly{q.y},aref,ws));}std::vector<KDResult> decoded;std::vector<G> answers;
    for(size_t i=0;i<classes.size();++i){bool forced=mode=="primary"||i==1;auto result=decoder.decode(classes[i],forced);std::vector<MTWitness> ws;auto value=mt_normalized(map,result.cycle.u,result.cycle.x,result.cycle.y,aref,ws).add(reference.neg());require(value==expected[i],"opaque KM reverse exact known composition");rejects([&]{require(cm_curve(f,result.cycle.u,result.cycle.x,result.cycle.y+CFPoly{Z(1)}).degree()<0,"changed decoded target y");},"changed decoded target y");decoded.push_back(result);answers.push_back(value);std::cerr<<"opaque decoder "<<labels[i]<<" RR="<<result.rr_dimension<<" projective rejects="<<result.chart_rejections.size()<<" shear rejects="<<result.shear_rejections.size()<<" passed\n";}
    rejects([&]{Class bad=cg;bad.w[0][0]=bad.w[0][0]+Z(1);decoder.validate(bad);},"off-ambient opaque input");require(!(answers[mode=="primary"?0:1].add(pg)==pg.times(3)),"changed opaque reverse result");
    std::cout<<"{\"scope\":\"P192-opaque-KM-to-divisor-and-transpose\",\"standing\":\"producer-unverified\",\"mode\":\""<<mode<<"\",\"L_B_dimension\":13,\"multiplier_dimension\":19,\"product_rank\":"<<decoder.product_rank<<",\"cases\":[";for(size_t i=0;i<classes.size();++i){if(i)std::cout<<',';std::cout<<"{\"label\":"<<std::quoted(labels[i])<<",\"input_class\":";pc_emit_class(classes[i]);std::cout<<",\"decoded\":";kd_emit(decoded[i]);std::cout<<",\"source_result\":";tr_emit_g(answers[i]);std::cout<<",\"source_expected\":";tr_emit_g(expected[i]);std::cout<<'}';}std::cout<<"],\"off_ambient_input_rejected\":true,\"changed_reverse_rejected\":true}\n";
}catch(const std::exception& e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
